questionvariables.text:
hits(L,s,tol) := length(sublist(L, lambda([v], is(abs(v-s) <= tol))));
matchset(L,S,tol) := is(length(L) = length(S)) and every(lambda([s], is(hits(L,s,tol) = 1)), S);
allgenuine(L,S,tol) := every(lambda([v], some(lambda([s], is(abs(v-s) <= tol)), S)), L);
validate_angles(ex) := if (setp(ex) or listp(ex)) and every(lambda([v], numberp(ev(v,simp))), if setp(ex) then listify(ex) else ex) then "" else "Type the angles as numbers inside curly brackets, separated by commas, for example {30, 150}. Do not type the degree sign.";
r1(v) := float(floor(10*v+1/2)/10);
ang1(v) := block([r], r: floor(10*v+1/2), if integerp(r/10) then string(r/10) else string(float(r/10)));
setraw(L) := if L = [] then "\\{\\,\\}" else sconcat("\\{", simplode(map(lambda([v], sconcat(ang1(v), "^\\circ")), sort(L)), ", "), "\\}");
degraw(v) := sconcat(ang1(v), "^\\circ");
setstr(L) := sconcat("\\(", setraw(L), "\\)");
angc(v) := block([al], al: float(acos(v)*180/%pi), if abs(al) < 1e-9 then [0,360] elseif abs(al-180) < 1e-9 then [180] else [al, 360-al]);
angs(v) := block([al], al: float(asin(v)*180/%pi), if abs(al) < 1e-9 then [0,180,360] elseif abs(al-90) < 1e-9 then [90] elseif abs(al+90) < 1e-9 then [270] elseif al > 0 then [al, 180-al] else [180-al, 360+al]);
qroots(A,B,C) := if A = 0 then (if B = 0 then [] else [-C/B]) elseif B^2-4*A*C < 0 then [] else [(-B-sqrt(B^2-4*A*C))/(2*A), (-B+sqrt(B^2-4*A*C))/(2*A)];
inrange(L) := sublist(L, lambda([v], is(abs(float(v)) <= 1+1e-12)));
uniqf(L) := unique(map(lambda([v], float(floor(10000*v+1/2)/10000)), L));
nice(v) := block([r], r: floor(1000*v+1/2)/1000, if integerp(r) then r else float(r));
res2(v) := block([r], r: floor(100*v+1/2)/100, if integerp(r) then string(r) else string(float(r)));
tm(n, s) := if n = 0 then "" elseif n = 1 then sconcat(" + ", s) elseif n = -1 then sconcat(" - ", s) elseif n > 0 then sconcat(" + ", string(n), s) else sconcat(" - ", string(-n), s);
tc(n) := if n = 0 then "" elseif n > 0 then sconcat(" + ", string(n)) else sconcat(" - ", string(-n));
lead(n, s) := if n = 1 then s elseif n = -1 then sconcat("-", s) else sconcat(string(n), s);
sind(t) := sin(%pi*t/180);
cosd(t) := cos(%pi*t/180);
deg(ex) := subst([sin=sind, cos=cosd], ex);
badkind(ex) := listp(ex) or setp(ex) or (not atom(ex) and member(op(ex), [">", "<", ">=", "<=", "#", "and", "or", "not", "nounand", "nounor", "nounnot"]));
validate_wave(ex) := block([cy], if badkind(ex) or not every(lambda([v], member(v, [x, y])), listofvars(ex)) or freeof(x, ex) then return("Type one equation of the form y = ..., such as y=2*sin(3*x), with x for the angle in degrees."), if not atom(ex) and op(ex) = "=" then (cy: ev(ratsimp(diff(lhs(ex)-rhs(ex), y)), simp), if freeof(x, cy) and freeof(y, cy) and is(cy # 0) then "" else "Type one equation of the form y = ..., such as y=2*sin(3*x), with x for the angle in degrees.") elseif freeof(y, ex) then "" else "Type one equation of the form y = ..., such as y=2*sin(3*x), with x for the angle in degrees.");
/* Design: equation of a wave after a sequence of three transformations. x and y are formal symbols only. Source: adapted from SMP AS/A2 Core 3, Chapter 3, Section B, Example 3 and Exercise B, Q2. */
L: [[1,2,1/2,30,1],[0,3,2,60,-1],[1,3,1/3,20,2],[0,2,1/2,-45,1],[1,4,2,-90,-2],[0,1/2,1/3,30,1],[1,2,3,90,-1],[0,3,1/2,60,2],[1,5,1/4,15,-3],[0,2,2,-120,3]];
ix: 1+rand(10);
fs: L[ix][1]; a: L[ix][2]; k: L[ix][3]; h: L[ix][4]; d: L[ix][5];
fname: if fs = 1 then "\\sin" else "\\cos";
dnum(v) := if integerp(v) then string(v) else string(float(v));
bxs(b) := if b = 1 then " x" elseif integerp(b) then sconcat(" ", string(b), "x") elseif num(b) = 1 then sconcat("\\tfrac{x}{", string(denom(b)), "}") else sconcat("\\tfrac{", string(num(b)), "x}{", string(denom(b)), "}");
F(t) := if fs = 1 then sin(t) else cos(t);
bb: 1/k;
ta: a*F(bb*x - bb*h) + d;
tunexp: a*F(bb*(x-h)) + d;
dord: a*F(bb*x - h) + d; drec: a*F(k*(x-h)) + d; dsgn: a*F(bb*(x+h)) + d;
tans1: y = ta; tans2: y = tunexp; tdord: y = dord; tdrec: y = drec; tdsgn: y = dsgn; tplus: y = ta+1;
samp: [0, 23, 61, 110, 157, 204, 251, 299, 340];
tv: map(lambda([v], float(ev(deg(ta), x=v))), samp);
vord: map(lambda([v], float(ev(deg(dord), x=v))), samp);
vrec: map(lambda([v], float(ev(deg(drec), x=v))), samp);
vsgn: map(lambda([v], float(ev(deg(dsgn), x=v))), samp);
ad: dnum(a);
step2: sconcat(ad, fname, bxs(bb));
trev: ta = y;
/* Two points followed through the three transformations, for the generic feedback. */
sx1: if fs = 1 then 90 else 0; sx0: if fs = 1 then 0 else 90;
X1: sx1*k + h; Y1: a + d; X0: sx0*k + h; Y0: d;

feedbackvariables.text:
e0: if not atom(ans1) and op(ans1) = "=" then lhs(ans1)-rhs(ans1) else false;
e1: if e0 = false then ans1 else -subst(y=0, e0)/ratsimp(diff(e0, y));
lv: map(lambda([v], float(ev(deg(e1), x=v))), samp);
nearv(u) := is(lmax(abs(lv - u)) < 0.001);
own1: float(ev(deg(e1), x=X1)); own0: float(ev(deg(e1), x=X0));
ownok: numberp(own1) and numberp(own0);
